    (SELECT jsonb_object_agg(t.lang, wk.p || s.week || ' · ' || replace(replace(replace(replace(t.name, '{n}', s.n), '{d}', s.d), '{m}', s.minutes::text), ' 1×', ' '))
       FROM tpl t JOIN wk USING (lang) WHERE t.typ = s.typ) AS names,
    (SELECT jsonb_object_agg(t.lang, t.obj || ' ' || CASE WHEN s.k = 1 THEN i.one ELSE replace(i.many, '{k}', s.k::text) END)
       FROM tpl t JOIN ind i USING (lang) WHERE t.typ = s.typ) AS objs,
    (SELECT jsonb_object_agg(t.lang, t.info) FROM tpl t WHERE t.typ = s.typ) AS infos
  FROM s
)
INSERT INTO public.training_sessions (name, info, objectif, session_json, total_duration, is_test, live_comments, translations_json, aero_duration_sec)
SELECT b.skey || '_name', b.skey || '_info', b.skey || '_objectif',
  jsonb_build_object('nom', b.names ->> 'fr', 'infos', '', 'duration', b.minutes, 'UnitDisplay', '% FTP', 'blocks', b.blocks),
  b.minutes, false, b.lc,
  jsonb_build_object('name', b.names, 'objectif', b.objs, 'info', b.infos, 'live_comments', '{"triathlon_long_12w_lc_start": {"fr": "Passe en TT sur les prolongateurs : épaules relâchées, tiens jusqu''au bout du bloc.", "en": "Get into TT on the extensions: shoulders relaxed, hold until the end of the block.", "es": "Ponte en TT en los acoples: hombros relajados, aguanta hasta el final del bloque.", "it": "Mettiti in TT sulle protesi: spalle rilassate, tieni fino alla fine del blocco.", "de": "Ab in TT auf den Aufsatz: Schultern locker, bis zum Ende des Blocks halten.", "nl": "Ga in TT op de opzetstukken: schouders ontspannen, houd vol tot het einde van het blok.", "pt": "Vá para o TT no clipe: ombros relaxados, aguente até o fim do bloco.", "ja": "エアロバーでTTに：肩の力を抜き、ブロックの最後まで維持しよう。", "tr": "Uzatmalarda TT''ye geç: omuzlar gevşek, blok bitene kadar koru."}, "triathlon_long_12w_lc_up": {"fr": "Relève-toi et récupère. Prochain bloc en TT.", "en": "Sit up and recover. Next block in TT.", "es": "Incorpórate y recupera. Próximo bloque en TT.", "it": "Rialzati e recupera. Prossimo blocco in TT.", "de": "Aufrichten und erholen. Nächster Block in TT.", "nl": "Kom overeind en herstel. Volgend blok in TT.", "pt": "Levante o tronco e recupere. Próximo bloco em TT.", "ja": "上体を起こして回復。次のブロックはTTで。", "tr": "Doğrul ve toparlan. Sonraki blok TT''de."}, "triathlon_long_12w_lc_mid": {"fr": "Mi-bloc : vérifie ta tête et tes épaules, reste bas et relâché.", "en": "Halfway: check your head and shoulders, stay low and relaxed.", "es": "Mitad del bloque: revisa cabeza y hombros, sigue abajo y relajado.", "it": "Metà blocco: controlla testa e spalle, resta basso e rilassato.", "de": "Halbzeit: Kopf und Schultern prüfen, tief und locker bleiben.", "nl": "Halverwege: check je hoofd en schouders, blijf laag en ontspannen.", "pt": "Metade do bloco: confira cabeça e ombros, fique baixo e relaxado.", "ja": "ブロックの半分：頭と肩を確認、低くリラックスしたまま。", "tr": "Blok ortası: başını ve omuzlarını kontrol et, alçak ve gevşek kal."}, "triathlon_long_12w_lc_recup": {"fr": "Récupère en TT : reste sur les prolongateurs, ton cerveau associe la position au repos.", "en": "Recover in TT: stay on the extensions, your brain links the position with rest.", "es": "Recupera en TT: sigue en los acoples, tu cerebro asocia la posición al descanso.", "it": "Recupera in TT: resta sulle protesi, il cervello associa la posizione al riposo.", "de": "Erhole dich in TT: Bleib auf dem Aufsatz, dein Gehirn verbindet die Position mit Ruhe.", "nl": "Herstel in TT: blijf op de opzetstukken, je brein koppelt de houding aan rust.", "pt": "Recupere em TT: fique no clipe, seu cérebro associa a posição ao descanso.", "ja": "TTで回復：エアロバーに乗ったまま。脳がこの姿勢を休息と結びつけます。", "tr": "TT''de toparlan: uzatmalarda kal, beynin pozisyonu dinlenmeyle ilişkilendirir."}}'::jsonb),
  b.aero
FROM built b
WHERE NOT EXISTS (SELECT 1 FROM public.training_sessions ts WHERE ts.name = b.skey || '_name');

INSERT INTO public.training_plans (name_key, description_key, objective_key, duration_weeks, difficulty, plan_type, sessions_per_week, is_active, translations_json)
SELECT 'triathlon_long_12w_name', 'triathlon_long_12w_description', 'triathlon_long_12w_objective', 12, 'advanced', 'training', 4, true, '{"name": {"fr": "Triathlon longue distance (70.3 et Ironman) en aéro", "en": "Long-distance triathlon (70.3 and Ironman) in aero", "es": "Triatlón de larga distancia (70.3 e Ironman) en aero", "it": "Triathlon lungo (70.3 e Ironman) in aero", "de": "Triathlon-Langdistanz (70.3 und Ironman) in Aero", "nl": "Lange-afstandstriatlon (70.3 en Ironman) in aero", "pt": "Triatlo de longa distância (70.3 e Ironman) em aero", "ja": "ロングディスタンス・トライアスロン（70.3・アイアンマン）エアロ", "tr": "Aero''da uzun mesafe triatlon (70.3 ve Ironman)"}, "objective": {"fr": "Tenir la position TT 90 minutes d''affilée à l''allure 70.3 (85-90 % FTP) et 2 h 30 d''affilée en endurance, sans se relever pour soulager la nuque.", "en": "Hold the TT position for 90 minutes in a row at 70.3 pace (85-90% FTP) and 2 h 30 in a row at endurance pace, without sitting up to relieve your neck.", "es": "Mantener la posición TT 90 minutos seguidos a ritmo 70.3 (85-90 % FTP) y 2 h 30 seguidas en resistencia, sin incorporarte para aliviar el cuello.", "it": "Tenere la posizione TT 90 minuti di fila al ritmo 70.3 (85-90 % FTP) e 2 h 30 di fila in resistenza, senza rialzarti per sgravare il collo.", "de": "Die TT-Position 90 Minuten am Stück im 70.3-Tempo (85-90 % FTP) und 2 h 30 am Stück im Grundlagentempo halten, ohne dich zur Entlastung des Nackens aufzurichten.", "nl": "De TT-houding 90 minuten aan één stuk op 70.3-tempo (85-90 % FTP) en 2 u 30 aan één stuk op duurtempo vasthouden, zonder overeind te komen om je nek te ontlasten.", "pt": "Manter a posição TT 90 minutos seguidos no ritmo 70.3 (85-90 % FTP) e 2 h 30 seguidas em resistência, sem levantar para aliviar o pescoço.", "ja": "70.3ペース（85〜90 % FTP）で90分連続、持久ペースで2時間30分連続のTTを保ち、首を楽にするために起き上がらない。", "tr": "TT pozisyonunu 70.3 temposunda (%85-90 FTP) aralıksız 90 dakika ve dayanıklılık temposunda aralıksız 2 sa 30 koru, enseyi rahatlatmak için doğrulma."}, "description": {"fr": "12 semaines pour le vélo d''un 70.3 ou d''un Ironman. Allure triathlon en TT de 2×15'' à 90'' d''affilée, tempo jusqu''à 75 minutes, sweet spot et PMA, une sortie longue TT par semaine jusqu''à 2 h 50. Semaine 12 : affûtage avant la course.", "en": "12 weeks for the bike leg of a 70.3 or an Ironman. Triathlon pace in TT from 2×15'' to 90'' in a row, tempo up to 75 minutes, sweet spot and VO2max, one long TT ride a week up to 2 h 50. Week 12: taper before the race.", "es": "12 semanas para la bici de un 70.3 o un Ironman. Ritmo de triatlón en TT de 2×15'' a 90'' seguidos, tempo hasta 75 minutos, sweet spot y VO2max, una salida larga TT por semana hasta 2 h 50. Semana 12: puesta a punto antes de la carrera.", "it": "12 settimane per la frazione bici di un 70.3 o di un Ironman. Ritmo triathlon in TT da 2×15'' a 90'' di fila, tempo fino a 75 minuti, sweet spot e VO2max, un''uscita lunga TT a settimana fino a 2 h 50. Settimana 12: scarico prima della gara.", "de": "12 Wochen für die Radstrecke eines 70.3 oder Ironman. Triathlontempo in TT von 2×15'' bis 90'' am Stück, Tempo bis 75 Minuten, Sweet Spot und VO2max, eine lange TT-Fahrt pro Woche bis 2 h 50. Woche 12: Tapering vor dem Rennen.", "nl": "12 weken voor het fietsdeel van een 70.3 of een Ironman. Triatlontempo in TT van 2×15'' tot 90'' aan één stuk, tempo tot 75 minuten, sweet spot en VO2max, één lange TT-rit per week tot 2 u 50. Week 12: taperen voor de wedstrijd.", "pt": "12 semanas para a bike de um 70.3 ou de um Ironman. Ritmo de triatlo em TT de 2×15'' a 90'' seguidos, tempo até 75 minutos, sweet spot e VO2max, um treino longo TT por semana até 2 h 50. Semana 12: polimento antes da prova.", "ja": "70.3やアイアンマンのバイクのための12週間。TTでのトライアスロンペースは2×15''から90''連続まで、テンポは最大75分、スイートスポットとVO2max、週1回最大2時間50分のロングTTライド。12週目はレース前の調整。", "tr": "70.3 ya da Ironman bisiklet etabı için 12 hafta. TT''de triatlon temposu 2×15''''den aralıksız 90''''ya, 75 dakikaya kadar tempo, sweet spot ve VO2max, haftada bir 2 sa 50''ye kadar uzun TT sürüşü. 12. hafta: yarış öncesi toparlanma."}}'::jsonb
WHERE NOT EXISTS (SELECT 1 FROM public.training_plans WHERE name_key = 'triathlon_long_12w_name');

INSERT INTO public.plan_sessions (plan_id, training_session_id, week_number, session_number)
SELECT p.id, ts.id, v.week, v.num
FROM (VALUES (1, 1, 'triathlon_long_12w_w1s1_name'), (1, 2, 'triathlon_long_12w_w1s2_name'), (1, 3, 'triathlon_long_12w_w1s3_name'), (1, 4, 'triathlon_long_12w_w1s4_name'), (2, 1, 'triathlon_long_12w_w2s1_name'), (2, 2, 'triathlon_long_12w_w2s2_name'), (2, 3, 'triathlon_long_12w_w2s3_name'), (2, 4, 'triathlon_long_12w_w2s4_name'), (3, 1, 'triathlon_long_12w_w3s1_name'), (3, 2, 'triathlon_long_12w_w3s2_name'), (3, 3, 'triathlon_long_12w_w3s3_name'), (3, 4, 'triathlon_long_12w_w3s4_name'), (4, 1, 'triathlon_long_12w_w4s1_name'), (4, 2, 'triathlon_long_12w_w4s2_name'), (4, 3, 'triathlon_long_12w_w4s3_name'), (5, 1, 'triathlon_long_12w_w5s1_name'), (5, 2, 'triathlon_long_12w_w5s2_name'), (5, 3, 'triathlon_long_12w_w5s3_name'), (5, 4, 'triathlon_long_12w_w5s4_name'), (6, 1, 'triathlon_long_12w_w6s1_name'), (6, 2, 'triathlon_long_12w_w6s2_name'), (6, 3, 'triathlon_long_12w_w6s3_name'), (6, 4, 'triathlon_long_12w_w6s4_name'), (7, 1, 'triathlon_long_12w_w7s1_name'), (7, 2, 'triathlon_long_12w_w7s2_name'), (7, 3, 'triathlon_long_12w_w7s3_name'), (7, 4, 'triathlon_long_12w_w7s4_name'), (8, 1, 'triathlon_long_12w_w8s1_name'), (8, 2, 'triathlon_long_12w_w8s2_name'), (8, 3, 'triathlon_long_12w_w8s3_name'), (9, 1, 'triathlon_long_12w_w9s1_name'), (9, 2, 'triathlon_long_12w_w9s2_name'), (9, 3, 'triathlon_long_12w_w9s3_name'), (9, 4, 'triathlon_long_12w_w9s4_name'), (10, 1, 'triathlon_long_12w_w10s1_name'), (10, 2, 'triathlon_long_12w_w10s2_name'), (10, 3, 'triathlon_long_12w_w10s3_name'), (10, 4, 'triathlon_long_12w_w10s4_name'), (11, 1, 'triathlon_long_12w_w11s1_name'), (11, 2, 'triathlon_long_12w_w11s2_name'), (11, 3, 'triathlon_long_12w_w11s3_name'), (11, 4, 'triathlon_long_12w_w11s4_name'), (12, 1, 'triathlon_long_12w_w12s1_name'), (12, 2, 'triathlon_long_12w_w12s2_name'), (12, 3, 'triathlon_long_12w_w12s3_name')) AS v(week, num, session_name)
JOIN public.training_sessions ts ON ts.name = v.session_name
JOIN public.training_plans p ON p.name_key = 'triathlon_long_12w_name'
WHERE NOT EXISTS (SELECT 1 FROM public.plan_sessions ps WHERE ps.plan_id = p.id AND ps.training_session_id = ts.id);
